-- Avanti shipping: approve the metro zones so Standard Delivery prices on the live site.
-- Run once in Supabase (SQL Editor > New query > paste > Run), after migration 005 and BEFORE the
-- shipping update goes live. Safe for the current live site, which doesn't read this table.
-- Safe to run more than once: it only adds a new settings version when something actually changes.
--
-- What it does:
--   1. If no shipping settings have been saved yet, saves the starting settings from the client
--      spec v1.0 (3 Nov 2026) as version 1, exactly as the dashboard would on first use.
--   2. Saves a new version with these zones approved (all five metro zones the spec switches on).
--      Rates are the spec's Section 13 rates. Regional, remote, WA, TAS and NT stay switched off.
--      To approve fewer zones, delete them from the list on the line marked >>> below.
-- Nothing else is changed. Every version is kept, and can be restored in Dashboard > Shipping > History.

do $$
declare
  approve text[] := array['syd-metro', 'mel-metro', 'bne-metro', 'adl-metro', 'cbr-act'];   -- >>> zones to approve
  who text := 'Rowayne (approved via SQL for launch)';
  cur record; newcfg jsonb;
begin
  if not exists (select 1 from public.shipping_config_versions) then
    insert into public.shipping_config_versions (version, config, note, created_by)
