-banner":{"label":"Pull up banner (standard, in carry bag)","length_mm":900,"width_mm":150,"height_mm":150,"weight_g":4500,"per_package":1,"verify":true},"pull-up-banner-premium":{"label":"Pull up banner (premium, in carry bag)","length_mm":920,"width_mm":180,"height_mm":180,"weight_g":6500,"per_package":1,"verify":true},"cake-topper":{"label":"Cake topper (padded mailer)","length_mm":300,"width_mm":230,"height_mm":30,"weight_g":120,"per_package":5,"verify":true},"wallpaper-sample":{"label":"Wallpaper sample (envelope)","length_mm":250,"width_mm":180,"height_mm":10,"weight_g":50,"per_package":10,"verify":true}},"flatpack":{"boards":{"White E Flute 1.5mm":{"thickness_mm":1.5,"g_m2":400},"White B Flute 3mm":{"thickness_mm":3,"g_m2":550},"Kraft B Flute 3mm":{"thickness_mm":3,"g_m2":550}},"sizes":{},"verify":true},"catalogue":{"categories":{"corflute":{"profile":"rigid"},"acm-panels":{"profile":"rigid","material":"acm_3mm"},"foam-pvc":{"profile":"rigid"},"foamboard":{"profile":"rigid"},"enviroboard":{"profile":"rigid"},"posters":{"profile":"poster"},"window-graphics":{"profile":"rolled"},"floor-decals":{"profile":"rolled","material":"floor_decal"},"wallpaper":{"profile":"wallpaper"},"mailer-boxes":{"profile":"flatpack","formula":"mailer"},"shipping-cartons":{"profile":"flatpack","formula":"rsc"},"pull-up-banners":{"profile":"unit","unit":"pull-up-banner"},"cake-toppers":{"profile":"unit","unit":"cake-topper"},"a-frames":{"profile":"unit"}},"products":{"wallpaper-sample":{"profile":"unit","unit":"wallpaper-sample"},"premium-pull-up-banner-stands":{"profile":"unit","unit":"pull-up-banner-premium"},"double-sided-premium-pull-up-banner-stand":{"profile":"unit","unit":"pull-up-banner-premium"},"metal-face-a-frame":{"profile":"unit","unit_by_size":{"600mmW x 900mmH":"aframe-metal-600x900","900mmW x 1200mmH":"aframe-metal-900x1200"}},"corflute-insertable-a-frame":{"profile":"unit","unit_by_size":{"600mmW x 900mmH":"aframe-corflute-600x900","900mmW x 1200mmH":"aframe-corflute-900x1200"}}}},"poster_flat_sizes":["A4","A3"],"paper_sizes":{"A4":[210,297],"A3":[297,420],"A2":[420,594],"A1":[594,841],"A0":[841,1189]}}$seed$::jsonb, 'Starting settings from the client specification v1.0 (3 Nov 2026)', 'system (initial settings)');
  end if;

  select version, config into cur from public.shipping_config_versions order by version desc limit 1;

  select jsonb_set(cur.config, '{zones}', jsonb_agg(
           case when z->>'id' = any(approve) and coalesce(z->'approval'->>'status', '') <> 'approved'
                then jsonb_set(z, '{approval}', jsonb_build_object('status', 'approved', 'by', who, 'at', to_char(now() at time zone 'utc', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')))
                else z end order by ord))
    into newcfg
    from jsonb_array_elements(cur.config->'zones') with ordinality as t(z, ord);

  if newcfg is distinct from cur.config then
    insert into public.shipping_config_versions (version, config, note, created_by)
    values (cur.version + 1, newcfg, 'Approved metro zones for launch: ' || array_to_string(approve, ', '), who);
  end if;
end $$;

-- Check: the version now in use, and each zone's status. The approved zones should say approved.
select v.version as settings_version, z->>'name' as zone, (z->>'enabled')::boolean as enabled, z->'approval'->>'status' as approval
from (select version, config from public.shipping_config_versions order by version desc limit 1) v,
     jsonb_array_elements(v.config->'zones') z
where (z->>'enabled')::boolean
order by 2;
